css:
.band{position:relative; overflow:visible}   /* hiddenにすると全部死ぬ */

/* 縦組み見出しを境界の上から下へ通す */
.band .vhead{position:absolute; top:-70px; left:74px; z-index:2;
  writing-mode:vertical-rl; font-size:20px; line-height:2.1; letter-spacing:.05em}

/* 写真をパネルの天面より上から始める */
.panel{position:relative; background:#fff; border-radius:32px}
.panel .photo{position:absolute; top:-40px; right:24px; width:46%; z-index:2;
  border:4px solid #fff; border-radius:24px; box-shadow:0 6px 16px rgba(0,0,0,.06)}

/* 同色のまま面をまたぐ"橋" */
.num{position:absolute; left:12%; top:50%; translate:0 -50%; z-index:2;
  font-size:120px; font-weight:800; line-height:1; color:#d5fcef}
.panel--green{position:relative; z-index:1; background:#36C29F}

/* 非対称：上だけ出して右は面一（余白ゼロ） */
.card{border-radius:96px; overflow:visible;
  display:grid; grid-template-columns:1fr auto;
  padding:56px 0 56px 56px}                  /* 右padding 0 = 面一 */
.card img{margin-top:-10px; border-radius:32px}
